INSERT INTO parks (name, lat, lon, region) SELECT 'Everland', 37.2939, 127.2025, 'South Korea' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Everland');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Dragon Coaster', 'Everland', 'Steel', 'Zamperla', 'Zamperla Powered', NULL, NULL, NULL, 0, 68, 1987, '1987-02-11', 'day', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Dragon Coaster' AND park = 'Everland');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Dragon Coaster' AND c.park = 'Everland' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
